_sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_0p5 = RealNumber('0.5'); _sage_const_7 = Integer(7); _sage_const_2 = Integer(2); _sage_const_1000 = Integer(1000); _sage_const_3 = Integer(3); _sage_const_9 = Integer(9); _sage_const_4 = Integer(4)
