def coppersmith_howgrave_univariate(pol, modulus, beta, mm, tt, XX):
    """
    Coppersmith revisited by Howgrave-Graham
    
    finds a solution if:
    * b|modulus, b >= modulus^beta , 0 < beta <= 1
    * |x| < XX

    # Copyright : David Wong
    # Github : https://github.com/mimoo/RSA-and-LLL-attacks/blob/master/coppersmith.sage

    """
    #
    # init
    #
    dd = pol.degree()
    nn = dd * mm + tt

    #
    # checks
    #
    if not _sage_const_0  < beta <= _sage_const_1 :
        raise ValueError("beta should belongs in (0, 1]")

    if not pol.is_monic():
        raise ArithmeticError("Polynomial must be monic.")

    # Coppersmith revisited algo for univariate
    # change ring of pol and x
    polZ = pol.change_ring(ZZ)
    x = polZ.parent().gen()
    # compute polynomials
    gg = []
    for ii in range(mm):
        for jj in range(dd):
            gg.append((x * XX)**jj * modulus**(mm - ii) * polZ(x * XX)**ii)
    for ii in range(tt):
        gg.append((x * XX)**ii * polZ(x * XX)**mm)
    
    # construct lattice B
    BB = Matrix(ZZ, nn)
    for ii in range(nn):
        for jj in range(ii+_sage_const_1 ):
            BB[ii, jj] = gg[ii][jj]
    # LLL
    BB = BB.LLL()
    # transform shortest vector in polynomial    
    new_pol = _sage_const_0 
    for ii in range(nn):
        new_pol += x**ii * BB[_sage_const_0 , ii] / XX**ii
    # factor polynomial
    potential_roots = new_pol.roots()
    # test roots
    roots = []
    for root in potential_roots:
        if root[_sage_const_0 ].is_integer():
            result = polZ(ZZ(root[_sage_const_0 ]))
            if gcd(modulus, result) >= modulus**beta:
                roots.append(ZZ(root[_sage_const_0 ]))
    return roots


def get_p(N, pa):
    """Returns a factor p of N or None given N = pq and an approximation of p."""
    F = PolynomialRing(Zmod(N), implementation='NTL', names=('x',)); (x,) = F._first_ngens(1); 
    pol = x - pa
    dd = pol.degree()
    beta = _sage_const_0p5                              # we should have q >= N^beta
    epsilon = beta / _sage_const_7                      # <= beta/7
    mm = ceil(beta**_sage_const_2  / (dd * epsilon))    # optimized
    tt = floor(dd * mm * ((_sage_const_1 /beta) - _sage_const_1 ))   # optimized
    XX = ceil(N**((beta**_sage_const_2 /dd) - epsilon)) # we should have |diff| < X
    
    # Coppersmith
    
    roots = coppersmith_howgrave_univariate(pol, N, beta, mm, tt, XX)
    if roots:
        return pa - roots[_sage_const_0 ]

    
def get_approx_p_pm_q(N, e, x, y, prec=_sage_const_1000 ):
    """Returns an approximate p+q and p-q given N, e, x, y such that 

        ex - (p^4 - 1)(q^4 - 1)y = w and N=pq
     """
    # Increase the precision
    RF = RealField(prec)
    # Convert inputs to high-precision real numbers
    N, e, x, y = RF(N), RF(e), RF(x), RF(y)
    # Perform the computation with high precision
    p_plus_q = floor(sqrt(abs((N+_sage_const_1 )**_sage_const_2  - (e*x)/y)))
    p_minus_q = floor(sqrt(abs((N-_sage_const_1 )**_sage_const_2  - (e*x)/y)))
    return p_plus_q, p_minus_q

def factor_N(N, e, prec=None):
    """Returns the factors p, q of N or None given the public key (N, e). 
    """
    precision = prec if prec else _sage_const_3 *N.bit_length()
    r = (e)/(N**_sage_const_2  + _sage_const_1  - (_sage_const_9 /_sage_const_4 )*N)
    cf = r.continued_fraction()
    for i, xy in enumerate(cf.convergents()[_sage_const_1 :]):
        x = xy.denominator()
        y = xy.numerator()
        p_plus_q, p_minus_q = get_approx_p_pm_q(N, e, x, y, precision)
        pa = int((p_plus_q + p_minus_q)/_sage_const_2 )
        p = get_p(N, pa)
        if p:
            return p, N//p 
    return None, None

